INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0007-000000000001', 'b0000001-0000-0000-0000-000000000007', 'b0000000-0000-0000-0000-000000000001', 1, 'vocabulario-de-ropa', '{"es": "Vocabulario de Ropa", "en": "Clothing Vocabulary"}'::jsonb, '{"es": "Aprende el vocabulario de las prendas de ropa más comunes y usa ''wear'' para describir qué llevas puesto.", "en": "Learn vocabulary for common clothing items and use ''wear'' to describe what you are wearing."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "En esta lección vas a aprender el vocabulario de las prendas de ropa más comunes en inglés, y a usar el verbo ''wear'' (llevar puesto) para hablar de lo que la gente lleva.", "sections": [{"type": "table", "title": "PRENDAS DE ROPA", "headers": ["Inglés", "Español"], "rows": [["shirt", "camisa"], ["pants / trousers", "pantalones"], ["dress", "vestido"], ["shoes", "zapatos"], ["jacket", "chaqueta"], ["skirt", "falda"], ["socks", "calcetines"], ["hat", "sombrero / gorro"], ["sweater", "suéter / jersey"], ["jeans", "vaqueros / jeans"]]}, {"type": "explanation", "title": "EL VERBO WEAR (LLEVAR PUESTO)", "text": "Usamos el verbo ''wear'' para decir qué ropa lleva puesto alguien. En presente simple: ''I wear a jacket'' (hábito general) o ''He/She wears a hat.'' Ya conoces el presente continuo, así que también podemos decir ''I am wearing a sweater'' para hablar de ahora mismo. ''Pants'' es la palabra americana y ''trousers'' la británica; ambas significan pantalones."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I am wearing a blue shirt today.", "es": "Hoy llevo puesta una camisa azul."}, {"en": "She wears a dress to work.", "es": "Ella lleva un vestido para trabajar."}, {"en": "He is wearing black shoes and a jacket.", "es": "Él lleva zapatos negros y una chaqueta."}, {"en": "They wear jeans and sweaters in winter.", "es": "Ellos llevan vaqueros y suéteres en invierno."}]}, {"type": "note", "variant": "info", "text": "''Pants'' es plural pero se refiere a una sola prenda: decimos ''these pants'' o ''a pair of pants'', nunca ''a pants''. Lo mismo pasa con ''jeans'' y ''shoes''."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0007-0001-000000000001', 'b0000002-0000-0000-0007-000000000001', 1, 'flashcard', '{"text": "shirt"}'::jsonb, '{"text": "la camisa", "phonetic": "/ʃɜːrt/"}'::jsonb, NULL, NULL, '{"vocab:clothes"}'),
('b0000003-0001-0007-0002-000000000001', 'b0000002-0000-0000-0007-000000000001', 2, 'flashcard', '{"text": "dress"}'::jsonb, '{"text": "el vestido", "phonetic": "/dres/"}'::jsonb, NULL, NULL, '{"vocab:clothes"}'),
('b0000003-0001-0007-0003-000000000001', 'b0000002-0000-0000-0007-000000000001', 3, 'flashcard', '{"text": "jacket"}'::jsonb, '{"text": "la chaqueta", "phonetic": "/ˈdʒækɪt/"}'::jsonb, NULL, NULL, '{"vocab:clothes"}'),
('b0000003-0001-0007-0004-000000000001', 'b0000002-0000-0000-0007-000000000001', 4, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "pants", "es": "los pantalones"}, {"en": "shoes", "es": "los zapatos"}, {"en": "skirt", "es": "la falda"}, {"en": "socks", "es": "los calcetines"}]}'::jsonb, NULL, NULL, '{"vocab:clothes"}'),
('b0000003-0001-0007-0005-000000000001', 'b0000002-0000-0000-0007-000000000001', 5, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "hat", "es": "el sombrero"}, {"en": "sweater", "es": "el suéter"}, {"en": "jeans", "es": "los vaqueros"}, {"en": "shirt", "es": "la camisa"}]}'::jsonb, NULL, NULL, '{"vocab:clothes"}'),
('b0000003-0001-0007-0006-000000000001', 'b0000002-0000-0000-0007-000000000001', 6, 'multiple_choice', '{"text": "What do you wear on your feet?"}'::jsonb, '{"text": "shoes"}'::jsonb, '["hat", "jacket", "skirt"]'::jsonb, '{"es": "Los zapatos (shoes) se llevan en los pies."}'::jsonb, '{"vocab:clothes"}'),
('b0000003-0001-0007-0007-000000000001', 'b0000002-0000-0000-0007-000000000001', 7, 'multiple_choice', '{"text": "It is cold outside, so I am wearing a ___."}'::jsonb, '{"text": "sweater"}'::jsonb, '["skirt", "sock", "dress"]'::jsonb, '{"es": "Cuando hace frío, llevamos un suéter (sweater) para abrigarnos."}'::jsonb, '{"vocab:clothes"}'),
('b0000003-0001-0007-0008-000000000001', 'b0000002-0000-0000-0007-000000000001', 8, 'fill_blank', '{"text": "She ___ a red dress today."}'::jsonb, '{"text": "is wearing", "accepted": ["is wearing", "wears"]}'::jsonb, NULL, '{"es": "Podemos usar el presente continuo (''is wearing'') para hablar de ahora mismo."}'::jsonb, '{"vocab:clothes","grammar:present_continuous"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0007-000000000002', 'b0000001-0000-0000-0000-000000000007', 'b0000000-0000-0000-0000-000000000001', 2, 'tallas-y-frases-de-compra', '{"es": "Tallas y Frases de Compra", "en": "Sizes and Shopping Phrases"}'::jsonb, '{"es": "Aprende las tallas de ropa y las frases más útiles para comprar en una tienda.", "en": "Learn clothing sizes and the most useful phrases for shopping in a store."}'::jsonb, 'vocabulary', 22, 13, '{"intro": "Ahora vas a aprender las tallas de ropa en inglés y las frases más útiles que necesitas para ir de compras: pedir tu talla, preguntar el precio y decir si algo te gusta o no.", "sections": [{"type": "table", "title": "TALLAS", "headers": ["Inglés", "Español"], "rows": [["small (S)", "pequeña"], ["medium (M)", "mediana"], ["large (L)", "grande"], ["extra large (XL)", "extra grande"]]}, {"type": "table", "title": "FRASES ÚTILES PARA COMPRAR", "headers": ["Inglés", "Español"], "rows": [["Can I try this on?", "¿Puedo probarme esto?"], ["How much is it?", "¿Cuánto cuesta?"], ["Do you have this in a different size?", "¿Tiene esto en otra talla?"], ["Do you have this in a different color?", "¿Tiene esto en otro color?"], ["I''ll take it.", "Me lo llevo."], ["It''s too expensive.", "Es demasiado caro."], ["It''s too small / big.", "Es demasiado pequeño / grande."]]}, {"type": "explanation", "title": "CÓMO USAR ESTAS FRASES", "text": "''Can I try this on?'' se usa cuando quieres probarte una prenda en el probador. ''How much is it?'' sirve para preguntar el precio de una sola cosa; si son varias, decimos ''How much are they?''. ''Too'' + adjetivo significa ''demasiado'': ''too expensive'', ''too small'', ''too big''."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "Excuse me, can I try this on?", "es": "Disculpe, ¿puedo probarme esto?"}, {"en": "How much is this jacket?", "es": "¿Cuánto cuesta esta chaqueta?"}, {"en": "Do you have this shirt in a different size?", "es": "¿Tiene esta camisa en otra talla?"}, {"en": "It''s too expensive for me.", "es": "Es demasiado caro para mí."}, {"en": "I like it. I''ll take it.", "es": "Me gusta. Me lo llevo."}]}, {"type": "note", "variant": "tip", "text": "En muchas tiendas de países de habla inglesa, las tallas de ropa se escriben como letras (S, M, L, XL) en lugar de números."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0007-0001-000000000001', 'b0000002-0000-0000-0007-000000000002', 1, 'multiple_choice', '{"text": "What do you say when you want to try on a piece of clothing?"}'::jsonb, '{"text": "Can I try this on?"}'::jsonb, '["I''ll take it.", "How much is it?", "It''s too big."]'::jsonb, '{"es": "''Can I try this on?'' se usa para pedir permiso para probarse una prenda."}'::jsonb, '{"functional:shopping_phrases"}'),
('b0000003-0002-0007-0002-000000000001', 'b0000002-0000-0000-0007-000000000002', 2, 'multiple_choice', '{"text": "You want to know the price of a jacket. You ask:"}'::jsonb, '{"text": "How much is it?"}'::jsonb, '["Can I try this on?", "I''ll take it.", "Do you have this in a different color?"]'::jsonb, '{"es": "''How much is it?'' pregunta por el precio."}'::jsonb, '{"functional:shopping_phrases"}'),
('b0000003-0002-0007-0003-000000000001', 'b0000002-0000-0000-0007-000000000002', 3, 'multiple_choice', '{"text": "This shirt only comes in blue, but you want it in red. You ask:"}'::jsonb, '{"text": "Do you have this in a different color?"}'::jsonb, '["It''s too expensive.", "I''ll take it.", "How much is it?"]'::jsonb, '{"es": "Cuando queremos otro color, preguntamos ''Do you have this in a different color?''"}'::jsonb, '{"functional:shopping_phrases"}'),
('b0000003-0002-0007-0004-000000000001', 'b0000002-0000-0000-0007-000000000002', 4, 'fill_blank', '{"text": "This hat is too ___ for me. I need a bigger size."}'::jsonb, '{"text": "small", "accepted": ["small"]}'::jsonb, NULL, '{"es": "Si necesita una talla más grande, es porque el sombrero es demasiado pequeño (small)."}'::jsonb, '{"vocab:sizes","functional:shopping_phrases"}'),
('b0000003-0002-0007-0005-000000000001', 'b0000002-0000-0000-0007-000000000002', 5, 'fill_blank', '{"text": "I like this dress. I''ll ___ it."}'::jsonb, '{"text": "take", "accepted": ["take"]}'::jsonb, NULL, '{"es": "''I''ll take it'' significa ''me lo llevo''."}'::jsonb, '{"functional:shopping_phrases"}'),
('b0000003-0002-0007-0006-000000000001', 'b0000002-0000-0000-0007-000000000002', 6, 'translation', '{"text": "¿Puedo probarme esta chaqueta?"}'::jsonb, '{"text": "Can I try this jacket on?", "accepted": ["Can I try this jacket on?", "Can I try on this jacket?"]}'::jsonb, NULL, NULL, '{"functional:shopping_phrases","vocab:clothes"}'),
('b0000003-0002-0007-0007-000000000001', 'b0000002-0000-0000-0007-000000000002', 7, 'translation', '{"text": "Es demasiado caro para mí."}'::jsonb, '{"text": "It''s too expensive for me.", "accepted": ["It''s too expensive for me.", "It is too expensive for me."]}'::jsonb, NULL, NULL, '{"functional:shopping_phrases"}'),
('b0000003-0002-0007-0008-000000000001', 'b0000002-0000-0000-0007-000000000002', 8, 'translation', '{"text": "¿Tiene esta camisa en talla mediana?"}'::jsonb, '{"text": "Do you have this shirt in medium?", "accepted": ["Do you have this shirt in medium?", "Do you have this shirt in a medium size?"]}'::jsonb, NULL, NULL, '{"functional:shopping_phrases","vocab:sizes"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0007-000000000003', 'b0000001-0000-0000-0000-000000000007', 'b0000000-0000-0000-0000-000000000001', 3, 'cuantificadores-some-y-any', '{"es": "Cuantificadores: Some y Any", "en": "Quantifiers: Some and Any"}'::jsonb, '{"es": "Aprende a usar ''some'' en frases afirmativas y ofertas, y ''any'' en negativas y preguntas.", "en": "Learn to use ''some'' in affirmative sentences and offers, and ''any'' in negatives and questions."}'::jsonb, 'grammar', 22, 14, '{"intro": "En esta lección vas a aprender ''some'' y ''any'', dos palabras muy importantes para hablar de cantidades sin decir un número exacto. Se usan con sustantivos contables en plural (shirts, shoes) y con sustantivos incontables (money, water).", "sections": [{"type": "table", "title": "SOME Y ANY", "headers": ["Uso", "Ejemplo"], "rows": [["some — afirmativo", "I have some money."], ["some — ofertas y peticiones", "Can I have some water?"], ["any — negativo", "I don''t have any money."], ["any — preguntas", "Do you have any shirts in blue?"]]}, {"type": "explanation", "title": "CUÁNDO USAR SOME Y CUÁNDO ANY", "text": "Usamos ''some'' en frases afirmativas: ''I have some shirts'' (contable) o ''I have some money'' (incontable). Usamos ''any'' en frases negativas: ''I don''t have any shirts'' y en la mayoría de las preguntas: ''Do you have any shoes?'' Una excepción importante: cuando hacemos una oferta o una petición educada, usamos ''some'' incluso en una pregunta, por ejemplo ''Can I have some water, please?'' porque esperamos una respuesta afirmativa."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "I have some jackets in my closet.", "es": "Tengo algunas chaquetas en mi armario."}, {"en": "I don''t have any dresses.", "es": "No tengo ningún vestido."}, {"en": "Do you have any shirts in blue?", "es": "¿Tienes camisas en azul?"}, {"en": "Can I have some water, please?", "es": "¿Me das un poco de agua, por favor?"}, {"en": "There isn''t any money in my wallet.", "es": "No hay dinero en mi cartera."}]}, {"type": "note", "variant": "warning", "text": "No confundas: ''some'' no siempre es ''unos/algunos'' en una traducción literal, y ''any'' en negativo se traduce a menudo como ''ningún/ninguna'' en español, no como ''alguno''."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0007-0001-000000000001', 'b0000002-0000-0000-0007-000000000003', 1, 'multiple_choice', '{"text": "I have ___ shirts in my closet."}'::jsonb, '{"text": "some"}'::jsonb, '["any", "much", "many"]'::jsonb, '{"es": "En frases afirmativas usamos ''some''."}'::jsonb, '{"grammar:quantifiers_some_any"}'),
('b0000003-0003-0007-0002-000000000001', 'b0000002-0000-0000-0007-000000000003', 2, 'multiple_choice', '{"text": "Do you have ___ jeans in a large size?"}'::jsonb, '{"text": "any"}'::jsonb, '["some", "much", "a"]'::jsonb, '{"es": "En preguntas normalmente usamos ''any''."}'::jsonb, '{"grammar:quantifiers_some_any"}'),
('b0000003-0003-0007-0003-000000000001', 'b0000002-0000-0000-0007-000000000003', 3, 'multiple_choice', '{"text": "I don''t have ___ money with me today."}'::jsonb, '{"text": "any"}'::jsonb, '["some", "some of", "no"]'::jsonb, '{"es": "En frases negativas usamos ''any''."}'::jsonb, '{"grammar:quantifiers_some_any"}'),
('b0000003-0003-0007-0004-000000000001', 'b0000002-0000-0000-0007-000000000003', 4, 'fill_blank', '{"text": "Can I have ___ water, please?"}'::jsonb, '{"text": "some", "accepted": ["some"]}'::jsonb, NULL, '{"es": "En ofertas y peticiones educadas usamos ''some'', incluso en preguntas."}'::jsonb, '{"grammar:quantifiers_some_any"}'),
('b0000003-0003-0007-0005-000000000001', 'b0000002-0000-0000-0007-000000000003', 5, 'fill_blank', '{"text": "There isn''t ___ hat in this store in my size."}'::jsonb, '{"text": "any", "accepted": ["any"]}'::jsonb, NULL, '{"es": "Después de ''there isn''t'' (negativo) usamos ''any''."}'::jsonb, '{"grammar:quantifiers_some_any"}'),
('b0000003-0003-0007-0006-000000000001', 'b0000002-0000-0000-0007-000000000003', 6, 'translation', '{"text": "Tengo algunos vestidos nuevos."}'::jsonb, '{"text": "I have some new dresses.", "accepted": ["I have some new dresses."]}'::jsonb, NULL, NULL, '{"grammar:quantifiers_some_any","vocab:clothes"}'),
('b0000003-0003-0007-0007-000000000001', 'b0000002-0000-0000-0007-000000000003', 7, 'translation', '{"text": "¿Tienes zapatos en negro?"}'::jsonb, '{"text": "Do you have any shoes in black?", "accepted": ["Do you have any shoes in black?"]}'::jsonb, NULL, NULL, '{"grammar:quantifiers_some_any","vocab:clothes"}'),
('b0000003-0003-0007-0008-000000000001', 'b0000002-0000-0000-0007-000000000003', 8, 'error_correction', '{"text": "I don''t have some jackets in my closet.", "error_word": "some"}'::jsonb, '{"text": "any"}'::jsonb, '["a", "much"]'::jsonb, '{"es": "En frases negativas usamos ''any'', no ''some'': ''I don''t have any jackets.''"}'::jsonb, '{"grammar:quantifiers_some_any"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0007-000000000004', 'b0000001-0000-0000-0000-000000000007', 'b0000000-0000-0000-0000-000000000001', 4, 'cuantificadores-much-many-a-lot-of', '{"es": "Cuantificadores: Much, Many, A Lot Of", "en": "Quantifiers: Much, Many, A Lot Of"}'::jsonb, '{"es": "Aprende a usar ''much'' con sustantivos incontables, ''many'' con contables, y ''a lot of'' con ambos.", "en": "Learn to use ''much'' with uncountable nouns, ''many'' with countable nouns, and ''a lot of'' with both."}'::jsonb, 'grammar', 23, 14, '{"intro": "En esta lección vas a aprender tres palabras más para hablar de cantidades grandes: ''much'', ''many'' y ''a lot of''. Cada una se usa con un tipo diferente de sustantivo.", "sections": [{"type": "table", "title": "MUCH, MANY, A LOT OF", "headers": ["Palabra", "Se usa con", "Ejemplo"], "rows": [["much", "incontables, en preguntas/negativas", "How much money do you have?"], ["many", "contables plural, en preguntas/negativas", "How many shirts do you have?"], ["a lot of", "ambos, en afirmativas/preguntas/negativas", "I have a lot of clothes."]]}, {"type": "explanation", "title": "CUÁNDO USAR CADA UNO", "text": "''Much'' se usa con sustantivos incontables (money, water, time) y aparece sobre todo en preguntas y frases negativas: ''How much money do you have?'', ''I don''t have much time.'' ''Many'' se usa con sustantivos contables en plural (shirts, shoes, jackets), también en preguntas y negativas: ''How many shoes do you have?'', ''I don''t have many jackets.'' ''A lot of'' es más flexible: funciona con ambos tipos de sustantivos y se usa normalmente en frases afirmativas, aunque también puede usarse en preguntas: ''I have a lot of shirts'', ''I have a lot of money.''"}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "How much money do you have?", "es": "¿Cuánto dinero tienes?"}, {"en": "How many shirts do you have?", "es": "¿Cuántas camisas tienes?"}, {"en": "I have a lot of clothes in my closet.", "es": "Tengo mucha ropa en mi armario."}, {"en": "I don''t have much time to go shopping.", "es": "No tengo mucho tiempo para ir de compras."}, {"en": "She doesn''t have many dresses.", "es": "Ella no tiene muchos vestidos."}]}, {"type": "note", "variant": "tip", "text": "Truco fácil: si el sustantivo tiene plural con ''s'' (shirts, shoes), usa ''many''. Si no tiene plural (money, water, time), usa ''much''. ''A lot of'' siempre es una opción segura para frases afirmativas."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0004-0007-0001-000000000001', 'b0000002-0000-0000-0007-000000000004', 1, 'multiple_choice', '{"text": "How ___ money do you have?"}'::jsonb, '{"text": "much"}'::jsonb, '["many", "some", "any"]'::jsonb, '{"es": "''Money'' es incontable, así que usamos ''much'' en la pregunta."}'::jsonb, '{"grammar:quantifiers_much_many"}'),
('b0000003-0004-0007-0002-000000000001', 'b0000002-0000-0000-0007-000000000004', 2, 'multiple_choice', '{"text": "How ___ shirts do you have?"}'::jsonb, '{"text": "many"}'::jsonb, '["much", "some", "any"]'::jsonb, '{"es": "''Shirts'' es contable plural, así que usamos ''many''."}'::jsonb, '{"grammar:quantifiers_much_many"}'),
('b0000003-0004-0007-0003-000000000001', 'b0000002-0000-0000-0007-000000000004', 3, 'multiple_choice', '{"text": "I have ___ clothes in my closet."}'::jsonb, '{"text": "a lot of"}'::jsonb, '["much", "many", "any"]'::jsonb, '{"es": "En frases afirmativas, ''a lot of'' funciona con sustantivos contables e incontables."}'::jsonb, '{"grammar:quantifiers_much_many"}'),
('b0000003-0004-0007-0004-000000000001', 'b0000002-0000-0000-0007-000000000004', 4, 'fill_blank', '{"text": "She doesn''t have ___ time to go shopping today."}'::jsonb, '{"text": "much", "accepted": ["much"]}'::jsonb, NULL, '{"es": "''Time'' es incontable y la frase es negativa, así que usamos ''much''."}'::jsonb, '{"grammar:quantifiers_much_many"}'),
('b0000003-0004-0007-0005-000000000001', 'b0000002-0000-0000-0007-000000000004', 5, 'fill_blank', '{"text": "He doesn''t have ___ jackets for winter."}'::jsonb, '{"text": "many", "accepted": ["many"]}'::jsonb, NULL, '{"es": "''Jackets'' es contable plural y la frase es negativa, así que usamos ''many''."}'::jsonb, '{"grammar:quantifiers_much_many"}'),
('b0000003-0004-0007-0006-000000000001', 'b0000002-0000-0000-0007-000000000004', 6, 'translation', '{"text": "¿Cuántos zapatos tienes?"}'::jsonb, '{"text": "How many shoes do you have?", "accepted": ["How many shoes do you have?"]}'::jsonb, NULL, NULL, '{"grammar:quantifiers_much_many","vocab:clothes"}'),
('b0000003-0004-0007-0007-000000000001', 'b0000002-0000-0000-0007-000000000004', 7, 'translation', '{"text": "Tengo mucho dinero para comprar ropa."}'::jsonb, '{"text": "I have a lot of money to buy clothes.", "accepted": ["I have a lot of money to buy clothes."]}'::jsonb, NULL, NULL, '{"grammar:quantifiers_much_many"}'),
('b0000003-0004-0007-0008-000000000001', 'b0000002-0000-0000-0007-000000000004', 8, 'error_correction', '{"text": "How much shirts do you have?", "error_word": "much"}'::jsonb, '{"text": "many"}'::jsonb, '["some", "any"]'::jsonb, '{"es": "''Shirts'' es contable plural, así que la pregunta correcta es ''How many shirts do you have?''"}'::jsonb, '{"grammar:quantifiers_much_many"}');
